insert into fsp.glossary_topics (id, slug, icon, title_de, title_en, description_de, description_en, sort, published) values
('3ee20711-e029-486b-8430-9b6909a8b153', 'koerper', '🫀', 'Körper und Organe', 'Body and organs', 'Körperteile, Organe und Organsysteme – die Grundlage für jede Beschreibung von Beschwerden.', 'Body parts, organs and organ systems – the basis for describing any complaint.', 1, true),
('3c4fe655-cd02-40c7-8f01-ef5013324ff5', 'symptome', '🤒', 'Symptome und Beschwerden', 'Symptoms and complaints', 'Wie Patienten ihre Beschwerden beschreiben und wie Pflegekräfte sie genau erfragen und benennen.', 'How patients describe their complaints and how nurses ask about and name them precisely.', 2, true),
('3a4715fe-9712-4379-8dcc-b18a16cee3cd', 'krankheiten', '🩺', 'Krankheitsbilder', 'Diseases and conditions', 'Die häufigsten Erkrankungen im Pflegealltag – im Fachwort und verständlich erklärt.', 'The most common diseases in everyday nursing – technical term and plain explanation.', 3, true),
('3f46427f-e49b-4ce6-88cf-494d47eed270', 'fachwort-alltag', '🔁', 'Fachwort und Alltagssprache', 'Medical term and everyday language', 'In der Prüfung musst du Fachwörter für Patienten verständlich erklären und Patientenaussagen in Fachsprache übersetzen.', 'In the exam you must explain medical terms in plain language and turn patients'' words into medical language.', 4, true),
('382be1a4-d0f2-42dd-86f5-ba681d1d27fb', 'vitalzeichen', '📈', 'Vitalzeichen und Krankenbeobachtung', 'Vital signs and observation', 'Messen, beschreiben und weitergeben: Puls, Blutdruck, Atmung, Temperatur, Bewusstsein und mehr.', 'Measure, describe and report: pulse, blood pressure, breathing, temperature, consciousness and more.', 5, true),
('38d84842-2018-42df-8115-4e4e64da02ae', 'medikamente', '💊', 'Medikamente und Verabreichung', 'Medication and administration', 'Arzneiformen, Applikationswege, Dosierung und die sichere Gabe von Medikamenten.', 'Dosage forms, routes, dosing and safe administration of medication.', 6, true),
('36e3f392-d594-40a1-819d-b9ed5c0ea4d4', 'grundpflege', '🧼', 'Grundpflege und Körperpflege', 'Basic care and personal hygiene', 'Waschen, Mundpflege, Anziehen, Hilfe im Alltag – und wie man darüber mit Patienten spricht.', 'Washing, oral care, dressing, daily support – and how to talk about it with patients.', 7, true),
('38575f62-9cbc-4caf-8699-353b1cbf99ab', 'mobilisation', '🛏️', 'Mobilisation und Lagerung', 'Mobilisation and positioning', 'Patienten bewegen, lagern und sicher transferieren – mit den richtigen Hilfsmitteln.', 'Moving, positioning and safely transferring patients – with the right aids.', 8, true),
('32e375b8-e25f-4a94-8d15-042d78ab4189', 'prophylaxen', '🛡️', 'Prophylaxen', 'Prophylaxis', 'Vorbeugende Maßnahmen gegen typische Komplikationen – ein Kernthema in Prüfung und Praxis.', 'Preventive measures against typical complications – a core topic in the exam and in practice.', 9, true),
('3cace56d-d1b4-4a5f-85e1-099708ac904b', 'ernaehrung-ausscheidung', '🍽️', 'Ernährung und Ausscheidung', 'Nutrition and elimination', 'Essen, Trinken, Sonden, Urin und Stuhl – beobachten, beschreiben und dokumentieren.', 'Eating, drinking, feeding tubes, urine and stool – observe, describe and document.', 10, true),
('3277b6dc-a3ab-400c-8327-b62993b36460', 'wunden', '🩹', 'Wundversorgung', 'Wound care', 'Wunden beschreiben, versorgen und dokumentieren – von der OP-Wunde bis zum Dekubitus.', 'Describe, dress and document wounds – from surgical wounds to pressure ulcers.', 11, true),
('39891d42-ef1d-41a5-8dba-858be60a35fd', 'hygiene', '🧴', 'Hygiene und Infektionsschutz', 'Hygiene and infection control', 'Händedesinfektion, Schutzkleidung, Isolierung und steriles Arbeiten.', 'Hand disinfection, protective clothing, isolation and sterile technique.', 12, true),
('39947742-2725-4e1d-8024-aca91f60fc59', 'diagnostik', '🔬', 'Untersuchungen und Diagnostik', 'Examinations and diagnostics', 'Blutabnahme, Bildgebung und Untersuchungen – Patienten vorbereiten und verständlich informieren.', 'Blood tests, imaging and examinations – prepare patients and explain clearly.', 13, true),
('3ed8023c-f386-431b-806a-3a8e5bdae41c', 'notfall', '🚨', 'Notfall und Erste Hilfe', 'Emergencies and first aid', 'Notfälle erkennen, richtig handeln und klar kommunizieren.', 'Recognise emergencies, act correctly and communicate clearly.', 14, true),
('36c2faf4-e89f-4c6b-86b6-a833e5ca5b82', 'operation', '🏥', 'Operation und perioperative Pflege', 'Surgery and perioperative care', 'Vor und nach der Operation: Vorbereitung, Narkose, Überwachung und Schmerztherapie.', 'Before and after surgery: preparation, anaesthesia, monitoring and pain management.', 15, true),
('3fa8194b-0a6a-4aec-8c32-85530d8a37f0', 'dokumentation', '📋', 'Dokumentation und Übergabe', 'Documentation and handover', 'Pflegebericht, Pflegeplanung und strukturierte Übergabe – schriftlich und mündlich präzise.', 'Nursing notes, care planning and structured handover – precise in writing and speech.', 16, true),
('31f2ec1e-2007-488e-8d50-081b31f6eea9', 'kommunikation', '💬', 'Kommunikation mit Patienten und Angehörigen', 'Communication with patients and relatives', 'Wichtige Begriffe und Redemittel für Aufnahme, Aufklärung, schwierige Gespräche und Telefonate.', 'Key terms and phrases for admissions, explanations, difficult conversations and phone calls.', 17, true),
('3f0db557-a158-445e-83fc-932a81ccd2d7', 'recht-organisation', '⚖️', 'Krankenhaus, Berufe und Recht', 'Hospital, professions and law', 'Stationen, Berufsgruppen und rechtliche Grundlagen, die in der Prüfung vorkommen.', 'Wards, professions and legal basics that come up in the exam.', 18, true),
('33fa69fc-0258-40af-81f6-0aa7a4fe96eb', 'demenz-palliativ', '🕊️', 'Demenz, Palliativpflege und Sterbebegleitung', 'Dementia, palliative and end-of-life care', 'Menschen mit Demenz begleiten, Schmerzen lindern und am Lebensende würdevoll pflegen.', 'Support people with dementia, relieve pain and provide dignified end-of-life care.', 19, true),
('32bb6007-db1f-4d09-884a-b223413fc222', 'verben', '🏃', 'Wichtige Verben in der Pflege', 'Key verbs in nursing', 'Verben für Pflegehandlungen, Berichte und Übergaben – mit Perfektform.', 'Verbs for nursing tasks, reports and handovers – with perfect tense.', 20, true),
('37c848e6-3265-4852-8b80-e08dac059f7b', 'abkuerzungen', '🔤', 'Abkürzungen', 'Abbreviations', 'Abkürzungen aus Kurve, Pflegebericht und Übergabe – lesen, aussprechen und verstehen.', 'Abbreviations from charts, nursing reports and handovers – read, say and understand them.', 21, true)
